package main

import "fmt"

func resetCopy(n int) {
	n = 0 // changes only the copy
}

func reset(n *int) {
	*n = 0
}

func swap(a, b *int) {
	*a, *b = *b, *a
}

func main() {
	lives := 3
	resetCopy(lives)
	fmt.Println("after resetCopy:", lives)
	reset(&lives)
	fmt.Println("after reset:", lives)
	x, y := 1, 2
	swap(&x, &y)
	fmt.Println("swapped:", x, y)
}

