practice.solution:
package main

import "fmt"

func addBonusCopy(score int) {
	score += 10 // changes only the copy
}

func addBonus(score *int, bonus int) {
	*score += bonus
}

func order(a, b *int) {
	if *a > *b {
		*a, *b = *b, *a
	}
}

func main() {
	points := 90
	addBonusCopy(points)
	fmt.Println("after addBonusCopy:", points)
	addBonus(&points, 10)
	fmt.Println("after addBonus:", points)
	lo, hi := 8, 3
	order(&lo, &hi)
	fmt.Println("ordered:", lo, hi)
}

