package main

import "fmt"

func main() {
	nums := []int{1, 2, 3}
	fmt.Println("nums:", nums)
	var ptrs []*int
	for _, v := range nums {
		ptrs = append(ptrs, &v) // the same v every time
	}
	fmt.Println(*ptrs[0], *ptrs[1], *ptrs[2], ptrs[0] == ptrs[1])
	var good []*int
	for i := range nums {
		good = append(good, &nums[i])
	}
	fmt.Println(*good[0], *good[1], *good[2], good[0] == good[1])
	*good[1] = 20
	fmt.Println("nums:", nums)
}

