package main

import "fmt"

func main() {
	names := []string{"Ana", "Ben", "Cy"}
	fmt.Println("names:", names)
	var ptrs []*string
	for _, n := range names {
		ptrs = append(ptrs, &n) // the same n every time
	}
	fmt.Println(*ptrs[0], *ptrs[1], *ptrs[2], ptrs[0] == ptrs[2])
	var good []*string
	for i := range names {
		good = append(good, &names[i])
	}
	fmt.Println(*good[0], *good[1], *good[2], good[0] == good[2])
	*good[1] = "Bea"
	fmt.Println("names:", names)
}
